#!/usr/bin/env python3
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / 'data'
SITE = ROOT / 'site'

def money(n):
    return '$' + format(n, ',.0f')

def main():
    SITE.mkdir(exist_ok=True)
    spend = json.loads((DATA / 'saas_spend.json').read_text())
    audit = json.loads((DATA / 'audit.json').read_text())
    ledger = json.loads((DATA / 'ledger.json').read_text())
    evidence = json.loads((DATA / 'evidence_pack.json').read_text()) if (DATA / 'evidence_pack.json').exists() else {}
    lab = json.loads((DATA / 'lab_readiness.json').read_text()) if (DATA / 'lab_readiness.json').exists() else {}
    site_data = {
        'spend': spend,
        'audit': audit,
        'ledger': ledger,
        'evidence': evidence,
        'lab': lab,
        'format': {
            'before': money(audit['before_annual_spend']),
            'after': money(audit['after_annual_spend']),
            'savings': money(audit['annual_savings']),
            'success_fee': '$' + format(audit['success_fee_amount'], ',.0f'),
            'balance': '$' + format(ledger['balance_cents'] / 100, ',.2f'),
        },
    }
    (SITE / 'data.json').write_text(json.dumps(site_data, indent=2))
    (SITE / 'index.html').write_text(INDEX)
    (SITE / 'styles.css').write_text(STYLES)
    (SITE / 'app.js').write_text(APP)
    print(json.dumps({'ok': True, 'site': str(SITE / 'index.html'), 'data': str(SITE / 'data.json')}, indent=2))

INDEX = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Otto Procurement Agent</title><link rel="stylesheet" href="styles.css"></head><body><header class="topbar"><div><p class="eyebrow">Hermes Agent Accelerated Business Hackathon</p><h1>Otto Procurement Agent</h1></div><div class="status-pill" id="paymentMode">loading</div></header><main><section class="hero card"><div><p class="eyebrow">Agent-run savings business</p><h2 id="headline">Loading audit...</h2><p id="thesis" class="lede"></p><div class="actions"><button id="replayBtn">Replay the agent run</button><span id="nextRun">Next run loading</span></div></div><div class="metrics"><div><b id="before">--</b><span>Before spend</span></div><div><b id="savings">--</b><span>Found savings</span></div><div><b id="fee">--</b><span>Stripe success fee</span></div></div></section><section class="steps"><article><b>1 / SCOUT</b><h3>Ingest messy SaaS evidence</h3><p>Invoices, usage logs, contracts, renewal windows, owners, and duplicate app categories.</p></article><article><b>2 / CHALLENGE</b><h3>Adversarial MoA council</h3><p>Savings Hunter, Finance Auditor, IT Reviewer, Risk Reviewer, and Aggregator agree or block.</p></article><article><b>3 / OPERATE</b><h3>Earn, spend, deliver</h3><p>Success-fee event, P&L, signed dry-run manifests, and buyer approval queue.</p></article></section><section class="card replay"><div class="section-head"><div><p class="eyebrow">Replay mode</p><h2>One-click audit trail</h2></div><span>Deterministic run from raw evidence to fee event</span></div><div id="runLog" class="runlog"></div></section><section class="card"><div class="section-head"><div><p class="eyebrow">Evidence cards</p><h2>Every dollar has fingerprints</h2></div><span id="generated"></span></div><p class="small">Before spend covers the full 20-vendor stack; evidence cards show the seven approved actions that survived risk review.</p><div id="evidenceCards" class="evidence-grid"></div></section><section class="grid"><article class="card"><p class="eyebrow">MoA council</p><h2>Visible challenger reasoning</h2><div id="council"></div><div id="blocked" class="blocked"></div></article><article class="card"><p class="eyebrow">Dry-run manifests</p><h2>Agent-prepared operations</h2><div id="manifests"></div></article></section><section class="grid"><article class="card"><p class="eyebrow">Treasury + P&L</p><h2>Profitable on run one</h2><div id="pnl" class="pnl"></div><div id="ledger"></div></article><article class="card"><p class="eyebrow">Controls + grounding</p><h2>Safety limits and public price checks</h2><div id="controls"></div><div id="sources"></div><div id="lab"></div><p class="small">Live customer-facing changes remain behind approval. The demo uses test-mode economics only.</p></article></section><section class="card proof"><p class="eyebrow">Submission proof</p><h2>Why this is a business, not a chatbot</h2><div><article><b>Earns</b><p>Success-fee checkout: 20% of annualized savings found by the agent.</p></article><article><b>Spends</b><p>MoA, ingestion, provisioning, hosting, and reinvestment debited under policy.</p></article><article><b>Runs ops</b><p>Produces evidence cards, blocks unsafe cuts, and signs dry-run action manifests.</p></article></div></section></main><footer>Built with Hermes Agent + MoA for the Nous Research x NVIDIA x Stripe hackathon.</footer><script src="app.js"></script></body></html>'''

STYLES = r'''*{box-sizing:border-box}body{margin:0;background:#0b1020;color:#fff;font-family:Inter,Arial,sans-serif;background-image:linear-gradient(rgba(255,255,255,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.045) 1px,transparent 1px);background-size:56px 56px}main,.topbar,footer{max-width:1220px;margin:auto}.topbar{display:flex;justify-content:space-between;align-items:center;padding:34px 20px 18px}.eyebrow{color:#ffd166;text-transform:uppercase;letter-spacing:.16em;font-size:13px;font-weight:900;margin:0 0 10px}h1{font-size:46px;letter-spacing:-.04em;margin:0;color:#fff}h2{font-size:34px;line-height:1.08;margin:0 0 14px;color:#fff}h3{margin:8px 0;color:#fff}.status-pill{border:1px solid #4ade80;color:#d1fae5;border-radius:99px;padding:9px 14px;background:#0f2a1a;font-weight:800}.card,.steps article{background:#111827;border:1px solid #40506c;border-radius:24px;box-shadow:0 20px 70px rgba(0,0,0,.35)}.hero{display:grid;grid-template-columns:1.7fr .8fr;gap:28px;padding:34px;margin:12px 20px}.lede{font-size:19px;line-height:1.58;color:#e5e7eb;max-width:820px}.actions{display:flex;gap:18px;align-items:center;margin-top:24px}button{background:#ffd166;border:0;border-radius:999px;padding:14px 20px;font-weight:900;color:#111}.actions span{color:#cbd5e1;font-weight:700}.metrics{display:grid;gap:16px}.metrics div{border:1px solid #50627f;border-radius:18px;padding:22px;background:#0f172a}.metrics b{display:block;color:#86efac;font-size:40px}.metrics span,.small{color:#e5e7eb}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:20px}.steps article{padding:22px}.steps b{color:#93c5fd}.steps p,.rec p,.proof p,.evidence p{color:#e5e7eb;line-height:1.45}.section-head{display:flex;justify-content:space-between;gap:16px;align-items:end}.section-head span{color:#f8fafc;font-size:14px;font-weight:700}.runlog{display:grid;gap:8px}.runitem{display:grid;grid-template-columns:80px 1fr auto;gap:14px;border:1px solid #334155;background:#0f172a;border-radius:14px;padding:10px 12px}.evidence-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.evidence{border:1px solid #50627f;border-radius:18px;padding:18px;background:#0f172a}.evidence:nth-child(odd):last-child{grid-column:1/-1}.evidence-top{display:flex;justify-content:space-between;gap:12px}.saving{color:#86efac;font-size:28px;font-weight:950;white-space:nowrap}.tags{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.tags span{background:#334155;border:1px solid #94a3b8;border-radius:99px;padding:6px 10px;color:#fff;font-size:13px;font-weight:800}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:20px}.grid .card,.proof.card,.replay.card,.card{padding:24px}.line{display:grid;grid-template-columns:1fr auto;gap:16px;border-bottom:1px solid #334155;padding:12px 0}.pos{color:#86efac}.neg{color:#fca5a5}.blocked{margin-top:18px;border:1px solid #f59e0b;background:#2a1f0b;border-radius:16px;padding:14px}.pnl{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-bottom:12px}.pnl div{background:#0f172a;border:1px solid #40506c;border-radius:14px;padding:12px}.proof{margin:20px}.proof>div{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.proof article{border:1px solid #50627f;border-radius:18px;padding:18px;background:#0f172a}a{color:#93c5fd}footer{padding:20px;color:#cbd5e1;text-align:center}@media(max-width:850px){.hero,.grid,.steps,.evidence-grid,.proof>div,.pnl{grid-template-columns:1fr}h1{font-size:34px}}'''

APP = r'''function money(n){return '$'+Number(n).toLocaleString()}function cents(c){var s=c<0?'-':'';return s+'$'+(Math.abs(c)/100).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}function title(k){var m={max_autonomous_ops_spend_cents:'Autonomous ops budget',live_spend_requires_human_approval:'Live spend approval',public_demo_dataset:'Demo dataset'};return m[k]||k.replaceAll('_',' ')}function val(k,v){if(k==='max_autonomous_ops_spend_cents')return '$'+(v/100).toLocaleString();if(typeof v==='boolean')return v?'Yes':'No';return v}function el(id){return document.getElementById(id)}function tags(list){return '<div class="tags">'+list.map(function(x){return '<span>'+x+'</span>'}).join('')+'</div>'}function boot(){fetch('data.json?ts='+Date.now()).then(function(r){return r.json()}).then(function(data){var a=data.audit,l=data.ledger,e=data.evidence||{};el('paymentMode').textContent=(l.payment.mode==='local_stripe_style_test_event'?'Payment loop ready':l.payment.mode.replaceAll('_',' '));el('headline').textContent=a.headline;el('thesis').textContent=a.thesis;el('before').textContent=data.format.before;el('savings').textContent=data.format.savings;el('fee').textContent=data.format.success_fee;el('generated').textContent='Generated '+a.generated_at;el('nextRun').textContent=e.next_run_at?'Next autonomous scan '+e.next_run_at:'Next scan scheduled';var log=(e.run_log||[]);el('runLog').innerHTML=log.map(function(x){return '<div class="runitem"><b>+'+x.t_plus_sec+'s</b><span>'+x.event+'</span><b class="pos">'+x.status+'</b></div>'}).join('');el('evidenceCards').innerHTML=(e.evidence_cards||[]).map(function(r){return '<article class="evidence"><div class="evidence-top"><h3>'+r.action+'</h3><div class="saving">'+money(r.annual_savings)+'</div></div><p>'+r.math+'</p><p>'+r.evidence.map(function(ev){return '<b>'+ev.kind+':</b> '+ev.finding}).join('<br>')+'</p>'+tags(['fee if verified: '+money(r.success_fee_if_verified),'risk: '+r.risk,'confidence: '+r.confidence])+'</article>'}).join('');el('council').innerHTML=a.council_transcript.map(function(c){return '<div class="line"><span><b>'+c.model+'</b><br><span class="small">'+c.position+'</span></span></div>'}).join('');var blocked=(e.blocked_recommendations||[])[0];el('blocked').innerHTML=blocked?'<b>Blocked unsafe savings:</b><br>'+blocked.action+' ('+money(blocked.tempting_savings)+' tempting) — '+blocked.why:'';el('manifests').innerHTML=(e.dry_run_manifests||[]).map(function(x){return '<div class="line"><span><b>'+x.action_id+'</b> '+x.step+'<br><span class="small">target: '+x.target_system+' / rollback: '+x.rollback+'</span></span><b>'+x.signature+'</b></div>'}).join('');var p=e.agent_pnl||{};el('pnl').innerHTML=[['Customer net value',money(p.customer_net_first_year_value||0)],['Agent run cost',cents(Math.round((p.agent_operating_cost||0)*100))],['Contribution margin',money(p.contribution_margin||0)],['ROI multiple',(p.roi_multiple||0)+'x']].map(function(x){return '<div><span class="small">'+x[0]+'</span><br><b class="pos">'+x[1]+'</b></div>'}).join('');el('ledger').innerHTML=l.entries.map(function(e){return '<div class="line"><span>'+e.label+'<br><span class="small">'+e.timestamp+'</span></span><b class="'+(e.amount_cents>=0?'pos':'neg')+'">'+cents(e.amount_cents)+'</b></div>'}).join('')+'<div class="line"><span><b>Ending treasury</b></span><b class="pos">'+data.format.balance+'</b></div>';el('controls').innerHTML=Object.entries(l.safety_limits).map(function(kv){return '<div class="line"><span>'+title(kv[0])+'</span><b>'+val(kv[0],kv[1])+'</b></div>'}).join('');el('sources').innerHTML='<h3>Public price source checks</h3>'+Object.entries(e.public_price_sources||{}).map(function(kv){return '<div class="line"><span>'+kv[0]+'</span><b>'+kv[1].status+'</b></div>'}).join('');var lab=data.lab||{};var nv=lab.nvidia||{};el('lab').innerHTML='<h3>NVIDIA/private inference lane</h3><div class="line"><span>GPU on this runner</span><b>'+(nv.available?'Detected':'CPU fallback')+'</b></div><div class="line"><span>Fallback benchmark</span><b>'+((lab.cpu_fallback_benchmark||{}).ops_per_second||'n/a')+' ops/s</b></div><p class="small">'+(lab.deployment_story||'Production path is local/private inference for sensitive procurement data.')+'</p>';el('replayBtn').onclick=function(){document.querySelector('.replay').scrollIntoView({behavior:'smooth'});document.querySelectorAll('.runitem').forEach(function(n,i){n.style.opacity=.25;setTimeout(function(){n.style.opacity=1;n.style.borderColor='#86efac'},i*180)})}})}boot();setInterval(boot,30000);'''

if __name__ == '__main__':
    main()
